#include "tigersheets/main_window.hpp"
#include "tigersheets/grid.hpp"
#include "tigersheets/worksheet_view.hpp"
#include <QApplication>
#include <QMenu>
#include <QTemporaryDir>
#include <QTemporaryFile>
#include <QTest>
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
namespace {
void require(bool okay,const char* message){if(!okay)throw std::runtime_error(message);}
struct Fixture {
 MainWindow window;WorksheetView* view;WorksheetModel* model;
 Fixture(){window.resize(1280,720);window.show();window.activateWindow();QApplication::processEvents();view=window.findChild<WorksheetView*>("worksheet.grid");model=dynamic_cast<WorksheetModel*>(view->model());require(view&&model,"actual native drawing surface exists");require(model->setData(model->index(1,1),"12")&&model->setData(model->index(2,2),"=1+2")&&model->setData(model->index(3,3),"end"),"seed real cells without replacing their workbook");require(model->apply(Json::array({{{"type","set_style"},{"sheet",model->sheetId().toStdString()},{"row",3},{"col",3},{"style",{{"bold",true},{"note","keep"}}}}})),"seed independent cell style and note");view->setCurrentIndex(model->index(0,0));require(window.executeCommand("view.ribbon"),"collapse source ribbon");view->setFocus();QApplication::processEvents();}
 void command(int key){QTest::keyClick(view,Qt::Key_7,Qt::AltModifier);QApplication::processEvents();auto* menu=window.findChild<QMenu*>("tutorial.borderMenu");require(menu&&menu->isVisible(),"actual Alt7 Borders menu opens");QAction* chosen=nullptr;for(auto* action:menu->actions())if(action->property("ribbon.keyTip").toString()==QString(QChar(key)))chosen=action;require(chosen&&chosen->isEnabled(),"the requested source-visible drawing command is enabled with its native keytip");QTest::keyClick(menu,static_cast<Qt::Key>(key));QApplication::processEvents();require(!menu->isVisible(),"drawing command closes the native menu");}
};
void sharedDrawing(){
 for(bool erase:{true,false}){Fixture f;const auto id=f.model->sheetId().toStdString();require(f.model->apply(Json::array({{{"type","set_style"},{"sheet",id},{"row",2},{"col",3},{"style",{{"italic",true},{"border",{{"bottom",{{"style","thick"},{"color","#ff0000"}}},{"diagonalUp",{{"style","thin"},{"color","#0000ff"}}}}}}}}})),"prepare an imported opposing border outside drawing gesture");const auto before=f.window.currentSession().snapshot();f.command(erase?Qt::Key_E:Qt::Key_W);const auto point=f.view->visualRect(f.model->index(2,2)).center();QTest::mouseClick(f.view->viewport(),Qt::LeftButton,Qt::NoModifier,point);QApplication::processEvents();const auto own=f.model->cellStyle(2,2).value("border",Json::object()),neighbor=f.model->cellStyle(1,2).value("border",Json::object());require(erase?(!own.contains("top")&&!neighbor.contains("bottom")):(own.contains("top")&&neighbor.contains("bottom")&&own.at("top")==neighbor.at("bottom")),"Draw and Erase update the same physical edge including an unselected imported owner");require(f.model->cellStyle(1,2).at("italic")==true&&neighbor.contains("diagonalUp")&&f.model->raw(2,2)=="=1+2","drawing shared edge preserves unrelated neighbor styles and formulas");QTest::keyClick(f.view,Qt::Key_Escape);require(f.window.executeCommand("undo")&&f.window.currentSession().snapshotView().at("sheets")==before.at("sheets"),"shared drawing gesture is exactly one undo");}
}
void drawOuter(bool grid=false){
 Fixture f;const auto before=f.window.currentSession().snapshot();const auto selected=f.view->selectionModel()->selection();const auto current=f.view->currentIndex();f.command(grid?Qt::Key_G:Qt::Key_W);require(f.window.currentSession().snapshot()==before,"starting border drawing creates no workbook transaction");const auto first=f.view->visualRect(f.model->index(1,1)).center(),last=f.view->visualRect(f.model->index(3,3)).center();QTest::mousePress(f.view->viewport(),Qt::LeftButton,Qt::NoModifier,first);QTest::mouseMove(f.view->viewport(),last);QApplication::processEvents();require(f.window.currentSession().snapshot()==before,"held border gesture remains uncommitted");QTest::mouseRelease(f.view->viewport(),Qt::LeftButton,Qt::NoModifier,last);QApplication::processEvents();const Json edge={{"style","thin"},{"color","#000000"}};
 for(int row=1;row<=3;++row)for(int col=1;col<=3;++col){const auto border=f.model->cellStyle(row,col).value("border",Json::object());for(const auto& [side,expected]:std::initializer_list<std::pair<const char*,bool>>{{"top",grid||row==1},{"bottom",grid||row==3},{"left",grid||col==1},{"right",grid||col==3}}){require(border.contains(side)==expected,"Draw Border applies only the outer rectangle");if(expected)require(border.at(side)==edge,"Draw Border stores the selected native line style and color");}}
 require(f.model->raw(1,1)=="12"&&f.model->raw(2,2)=="=1+2"&&f.model->raw(3,3)=="end"&&f.model->cellStyle(2,2).at("note")=="keep"&&f.model->cellStyle(2,2).at("bold")==true,"drawing preserves actual inputs, formulas, unrelated styles and notes");require(f.view->currentIndex()==current&&f.view->selectionModel()->selection()==selected,"drawing does not replace the active worksheet selection");QTest::keyClick(f.view,Qt::Key_Escape);QApplication::processEvents();require(f.window.executeCommand("undo")&&f.window.currentSession().snapshotView().at("sheets")==before.at("sheets"),"one native Undo removes the whole completed border gesture");const auto stopped=f.window.currentSession().snapshot();QTest::mouseClick(f.view->viewport(),Qt::LeftButton,Qt::NoModifier,first);QApplication::processEvents();require(f.window.currentSession().snapshot()==stopped,"Escape restores ordinary selection without another border edit");
}
void drawStyled(){
 Fixture f;
 auto option=[&](int tip,const char* submenuName,const QString& value){QTest::keyClick(f.view,Qt::Key_7,Qt::AltModifier);QApplication::processEvents();auto* menu=f.window.findChild<QMenu*>("tutorial.borderMenu");require(menu&&menu->isVisible(),"actual Borders menu opens for drawing options");QTest::keyClick(menu,static_cast<Qt::Key>(tip));QApplication::processEvents();auto* submenu=menu->findChild<QMenu*>(submenuName);require(submenu&&submenu->isVisible(),"actual selected drawing submenu opens");QAction* chosen=nullptr;for(auto* action:submenu->actions())if(action->data().toString()==value)chosen=action;require(chosen&&chosen->isEnabled(),"the source drawing option is selectable");QTest::mouseClick(submenu,Qt::LeftButton,Qt::NoModifier,submenu->actionGeometry(chosen).center());QApplication::processEvents();};
 option(Qt::Key_I,"tutorial.borderLineColor","#ff0000");
 for(const auto* style:{"medium","thin","dashed","dotted","thick","double","hair","mediumDashed","dashDot","mediumDashDot","dashDotDot","mediumDashDotDot","slantDashDot","none"}){
  option(Qt::Key_Y,"tutorial.borderLineStyle",QString::fromLatin1(style));if(std::string_view(style)=="none"){Json borders=Json::object();for(const auto* side:{"top","bottom","left","right"})borders[side]={{"style","thin"},{"color","#000000"}};require(f.model->apply(Json::array({{{"type","set_style"},{"sheet",f.model->sheetId().toStdString()},{"row",3},{"col",3},{"style",{{"border",borders}}}}})),"seed real existing edges for the None drawing style");}const auto before=f.window.currentSession().snapshot();f.command(Qt::Key_W);const auto point=f.view->visualRect(f.model->index(2,2)).center();QTest::mouseClick(f.view->viewport(),Qt::LeftButton,Qt::NoModifier,point);QApplication::processEvents();const auto border=f.model->cellStyle(2,2).value("border",Json::object());for(const auto* side:{"top","bottom","left","right"}){if(std::string_view(style)=="none")require(!border.contains(side),"selected None line style removes the drawn edges");else require(border.contains(side)&&border.at(side)==Json{{"style",style},{"color","#ff0000"}},"actual drawing uses every selected native line style and remembered red line color");}QTest::keyClick(f.view,Qt::Key_Escape);require(f.window.executeCommand("undo")&&f.window.currentSession().snapshotView().at("sheets")==before.at("sheets"),"each selected-style drawing stroke remains one native Undo");
 }
}

void eraseRange(){
 Fixture f;const auto sheet=f.model->sheetId().toStdString();Json borders=Json::object();for(const auto* side:{"top","bottom","left","right"})borders[side]={{"style","thin"},{"color","#000000"}};Json operations=Json::array();for(int row=2;row<=4;++row)for(int col=2;col<=4;++col)operations.push_back({{"type","set_style"},{"sheet",sheet},{"row",row},{"col",col},{"style",{{"border",borders}}}});operations.push_back({{"type","set_style"},{"sheet",sheet},{"row",6},{"col",6},{"style",{{"border",borders}}}});require(f.model->apply(operations),"prepare bordered cells and an untouched border outside the erase gesture");
 const auto before=f.window.currentSession().snapshot();f.command(Qt::Key_E);const auto first=f.view->visualRect(f.model->index(1,1)).center(),last=f.view->visualRect(f.model->index(3,3)).center();QTest::mousePress(f.view->viewport(),Qt::LeftButton,Qt::NoModifier,first);QTest::mouseMove(f.view->viewport(),last);require(f.window.currentSession().snapshot()==before,"erasing has no history before mouse release");QTest::mouseRelease(f.view->viewport(),Qt::LeftButton,Qt::NoModifier,last);QApplication::processEvents();
 for(int row=1;row<=3;++row)for(int col=1;col<=3;++col){const auto border=f.model->cellStyle(row,col).value("border",Json::object());for(const auto* side:{"top","bottom","left","right"})require(!border.contains(side)||border.at(side).is_null(),"Erase Border clears all target cell edges");}
 require(f.model->cellStyle(5,5).at("border")==borders&&f.model->raw(1,1)=="12"&&f.model->raw(2,2)=="=1+2"&&f.model->cellStyle(2,2).at("note")=="keep"&&f.model->cellStyle(2,2).at("bold")==true,"erasing preserves formulas, notes, unrelated styles and borders outside the gesture");QTest::keyClick(f.view,Qt::Key_Escape);require(f.window.executeCommand("undo")&&f.window.currentSession().snapshotView().at("sheets")==before.at("sheets"),"one native Undo restores all erased borders");
}

}
int main(int argc,char** argv){QTemporaryFile screen;if(qEnvironmentVariable("QT_QPA_PLATFORM")=="offscreen"){screen.open();screen.write("{\"screens\":[{\"width\":1280,\"height\":800}]}");screen.flush();qputenv("QT_QPA_PLATFORM",QByteArray("offscreen:configfile=")+screen.fileName().toUtf8());}QApplication app(argc,argv);QTemporaryDir state;qputenv("TIGERSHEETS_STATE_DIR",state.path().toUtf8());try{if(argc>1&&std::string(argv[1])=="shared")sharedDrawing();else if(argc>1&&std::string(argv[1])=="styled")drawStyled();else if(argc>1&&std::string(argv[1])=="erase")eraseRange();else{drawOuter(argc>1&&std::string(argv[1])=="grid");if(argc==1)sharedDrawing();}std::cout<<"Native border drawing passed\n";}catch(const std::exception& error){std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
